#!/usr/bin/env node
// Writes src/brand-colours.generated.ts: the Volter brand's roles resolved to
// plain values, light and dark, for TypeScript that builds inline styles or
// sets a colour through an API (the toolbar badge). Committed like any
// generated source; regenerated by `npm run build`.
import { writeFile } from "node:fs/promises";
import { tokens } from "./brand.mjs";

function flatten(tree, prefix = "", out = {}) {
  for (const [key, value] of Object.entries(tree)) {
    if (value && typeof value === "object") flatten(value, `${prefix}${key}.`, out);
    else out[`${prefix}${key}`] = value;
  }
  return out;
}
const light = flatten(tokens.semantic);
const dark = flatten(tokens.semanticDark);
for (const role of Object.keys(light)) if (!(role in dark)) throw new Error(`brand role ${role} has no dark value`);
const block = (name, values, type = "") => `export const ${name}${type} = ${JSON.stringify(values, null, 2)} as const;\n`;
const source = [
  "// Generated by scripts/build-brand-colours.mjs from https://brand.volter.ai/tokens.json. Do not edit.",
  block("BRAND_LIGHT", light),
  "export type BrandRole = keyof typeof BRAND_LIGHT;",
  block("BRAND_DARK", dark, ": Record<BrandRole, string>").replace(" as const;", ";"),
  block("BRAND_FONT", tokens.font),
  block("BRAND_SHADOW", tokens.shadow),
].join("\n");
await writeFile(new URL("../src/brand-colours.generated.ts", import.meta.url), source);
console.log(`src/brand-colours.generated.ts: ${Object.keys(light).length} roles`);
